boolean reach(int[] nums, int i, int left) {     // can nums[i..] make exactly left?
    if (left == 0) return true;
    if (i == nums.length || left < 0) return false;
    if (memo[i][left] == null) memo[i][left] = reach(nums, i + 1, left - nums[i]) || reach(nums, i + 1, left);
